mapper.select:
select * 
from (
select rownum rn, file_id, file_name,
  extension, f.path_id, size, update_time
from file_path fp
join file f on fp.path_id=f.path_id

where 
path like '%'||#{searchWord}||'%'
order by file_name

) where rn between #{startRow and #{endRow}

mapper.update:
update file_path
set path=#{path}, access_id=#{accessId}
where path_id=#{pathId}
